def g():
 x=yield 2
 yield x+1
 return 7
a=g()
print(a.send(None),a.send(4))
try: next(a)
except StopIteration as e: print(e.value)
print(next(a,99))

def g():
 yield 1
g().send(3)

def g():
 print('bad')
 yield 1
a=g()
try: a.throw(KeyError)
except KeyError: print('new')
try: a.throw(ValueError('closed'))
except ValueError: print('closed')
print(next(a,8))

def g():
 try: yield 1
 except GeneratorExit: yield 2
 yield 3
a=g()
print(next(a))
try: a.close()
except RuntimeError: print('ignored')
print(next(a),a.close())

def g():
 try:
  for i in range(2):
   try: yield i
   finally: yield i+10
 finally: print('done')
a=list(g())
print(a[0],a[1],a[2],a[3])

def child():
 try:
  yield 1
 except ValueError:
  yield 2
 finally: print('child')
def parent():
 try: yield from child()
 finally: print('parent')
a=parent()
print(next(a),a.throw(ValueError))
print(a.close())

def g():
 try: next(a)
 except ValueError: print('running')
 yield 3
a=g()
print(next(a))

def g():
 try: raise ValueError('inside')
 except ValueError:
  yield 1
  raise
a=g()
print(next(a))
try: next(a)
except ValueError as e: print(str(e))

class A:
 def values(self):
  yield self.x
a=A()
a.x=5
print(next(a.values()))

def f(x):
 print(x)
 return x
a={f(x):f(x+10) for x in range(2)}
b={x%2 for x in range(4)}
print(a[1],len(b),1 in b)

def g():
 yield 1
 raise
a=g()
try: raise ValueError("caller")
except ValueError: print(next(a))
try: next(a)
except RuntimeError: print("isolated")

def child():
 try: yield 1
 except GeneratorExit: yield 2
def parent(): yield from child()
a=parent()
print(next(a))
try: a.throw(GeneratorExit("exit"))
except RuntimeError: print("ignored")

class D:
 def __iter__(self): return self
 def __next__(self): return 1
 @property
 def throw(self): raise AttributeError("missing")
def g(): yield from D()
a=g()
print(next(a))
try: a.throw(ValueError("original"))
except ValueError as e: print(str(e))
